-- Estrutura sem dados, obtida dos catálogos para testes de segurança.
create table public.investment_accounts (id uuid default gen_random_uuid() not null,user_id uuid,name text not null,institution text,color text,created_at timestamp with time zone default timezone('utc'::text, now()),institution_id uuid,account_type_id uuid,currency text default 'BRL'::text);
create table public.investment_records (id uuid default gen_random_uuid() not null,user_id uuid,account_id uuid,record_date date not null,initial_balance numeric default 0,final_balance numeric default 0,yield numeric default 0,created_at timestamp with time zone default timezone('utc'::text, now()));
create table public.mf_account_groups (id uuid default gen_random_uuid() not null,user_id uuid not null,parent_id uuid,name text not null,icon text,color text,show_in_summary boolean default true not null,sum_totals boolean default true not null,sort_order integer default 0 not null,created_at timestamp with time zone default timezone('utc'::text, now()) not null,updated_at timestamp with time zone default timezone('utc'::text, now()) not null);
create table public.mf_account_types (id uuid default gen_random_uuid() not null,user_id uuid not null,name text not null,icon text default '💳'::text not null,created_at timestamp with time zone default timezone('utc'::text, now()) not null,updated_at timestamp with time zone default timezone('utc'::text, now()) not null);
create table public.mf_accounts (id uuid default gen_random_uuid() not null,user_id uuid not null,name text not null,account_type text default 'CORRENTE'::text not null,initial_balance numeric(14,2) default 0 not null,color text,icon text,image_url text,closing_day integer,due_day integer,credit_limit numeric(14,2),sort_order integer default 0 not null,is_active boolean default true not null,created_at timestamp with time zone default timezone('utc'::text, now()) not null,updated_at timestamp with time zone default timezone('utc'::text, now()) not null,currency text default 'BRL'::text not null,linked_account_id uuid,profile_id uuid,archived_at timestamp with time zone,card_brand text,group_id uuid,ignore_in_totals boolean default false not null,closing_dynamic boolean default false not null,due_business_days boolean default false not null);
create table public.mf_budgets (id uuid default gen_random_uuid() not null,user_id uuid not null,name text not null,category_id uuid,tag_id uuid,account_id uuid,period_start date not null,period_end date not null,mode text default 'FIXED'::text not null,amount numeric(14,2),percent_of_income numeric(5,2),created_at timestamp with time zone default timezone('utc'::text, now()) not null,updated_at timestamp with time zone default timezone('utc'::text, now()) not null);
create table public.mf_card_settings (id uuid default gen_random_uuid() not null,card_id uuid not null,user_id uuid not null,effective_from text not null,closing_day integer,due_day integer,closing_dynamic boolean default false not null,due_business_days boolean default false not null,credit_limit numeric(14,2),linked_account_id uuid,created_at timestamp with time zone default now() not null);
create table public.mf_categories (id uuid default gen_random_uuid() not null,user_id uuid not null,name text not null,type text not null,parent_id uuid,color text,icon text,sort_order integer default 0 not null,is_archived boolean default false not null,created_at timestamp with time zone default timezone('utc'::text, now()) not null,updated_at timestamp with time zone default timezone('utc'::text, now()) not null);
create table public.mf_goal_contributions (id uuid default gen_random_uuid() not null,user_id uuid not null,goal_id uuid not null,kind text not null,amount numeric(14,2) not null,contribution_date date not null,notes text,created_at timestamp with time zone default timezone('utc'::text, now()) not null);
create table public.mf_goals (id uuid default gen_random_uuid() not null,user_id uuid not null,name text not null,target_amount numeric(14,2) not null,initial_amount numeric(14,2) default 0 not null,target_date date,account_id uuid,color text,icon text,status text default 'ACTIVE'::text not null,created_at timestamp with time zone default timezone('utc'::text, now()) not null,updated_at timestamp with time zone default timezone('utc'::text, now()) not null);
create table public.mf_import_batches (id uuid default gen_random_uuid() not null,user_id uuid not null,filename text not null,format text not null,status text default 'PENDING'::text not null,total_rows integer default 0 not null,created_at timestamp with time zone default timezone('utc'::text, now()) not null,updated_at timestamp with time zone default timezone('utc'::text, now()) not null,account_id uuid);
create table public.mf_import_rows (id uuid default gen_random_uuid() not null,user_id uuid not null,batch_id uuid not null,payload jsonb default '{}'::jsonb not null,suggested_transaction_id uuid,imported_transaction_id uuid,status text default 'NEW'::text not null,created_at timestamp with time zone default timezone('utc'::text, now()) not null);
create table public.mf_invoice_notifications (id uuid default gen_random_uuid() not null,user_id uuid not null,card_id uuid not null,close_iso date not null,sent_at timestamp with time zone default now() not null);
create table public.mf_invoices (id uuid default gen_random_uuid() not null,user_id uuid not null,card_id uuid not null,close_date date not null,due_date date,total numeric(14,2) default 0 not null,total_source text default 'derived'::text not null,paid_total numeric(14,2) default 0 not null,status text default 'OPEN'::text not null,paid_at date,notes text,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null);
create table public.mf_profiles (id uuid default gen_random_uuid() not null,user_id uuid not null,name text not null,color text default '#6366f1'::text not null,sort_order integer default 0 not null,created_at timestamp with time zone default now() not null);
create table public.mf_push_subscriptions (id uuid default gen_random_uuid() not null,user_id uuid not null,endpoint text not null,p256dh text not null,auth text not null,created_at timestamp with time zone default now() not null);
create table public.mf_responsibles (id uuid default gen_random_uuid() not null,user_id uuid not null,name text not null,email text,color text,is_main boolean default false not null,is_archived boolean default false not null,created_at timestamp with time zone default timezone('utc'::text, now()) not null,updated_at timestamp with time zone default timezone('utc'::text, now()) not null);
create table public.mf_restore_points (id uuid default gen_random_uuid() not null,user_id uuid not null,label text not null,payload jsonb default '{}'::jsonb not null,created_at timestamp with time zone default now() not null);
create table public.mf_saved_reports (id uuid default gen_random_uuid() not null,user_id uuid not null,name text not null,filters jsonb default '{}'::jsonb not null,created_at timestamp with time zone default timezone('utc'::text, now()) not null,updated_at timestamp with time zone default timezone('utc'::text, now()) not null);
create table public.mf_tags (id uuid default gen_random_uuid() not null,user_id uuid not null,name text not null,color text,created_at timestamp with time zone default timezone('utc'::text, now()) not null,updated_at timestamp with time zone default timezone('utc'::text, now()) not null);
create table public.mf_transaction_tags (transaction_id uuid not null,tag_id uuid not null,user_id uuid not null,created_at timestamp with time zone default timezone('utc'::text, now()) not null);
create table public.mf_transactions (id uuid default gen_random_uuid() not null,user_id uuid not null,account_id uuid not null,transfer_account_id uuid,type text not null,description text not null,amount numeric(14,2) not null,payment_date date not null,due_date date,effective_date date,status text default 'PENDENTE'::text not null,category_id uuid,responsible_id uuid,notes text,attachment_path text,recurrence text default 'NONE'::text not null,installments_current integer,installments_total integer,parent_transaction_id uuid,created_at timestamp with time zone default timezone('utc'::text, now()) not null,updated_at timestamp with time zone default timezone('utc'::text, now()) not null,invoice_close date,is_fixed boolean default false not null,email_sent boolean default false not null,auto_settle boolean default false not null);
create table public.mf_tx_links (transaction_id uuid not null,user_id uuid not null,trip_id uuid,trip_expense_id uuid,investment_account_id uuid,investment_record_id uuid,investment_delta numeric(14,2) default 0 not null,investment_created boolean default false not null,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null);
create table public.mf_user_prefs (user_id uuid not null,data jsonb default '{}'::jsonb not null,updated_at timestamp with time zone default now() not null);
create table public.trip_expenses (id uuid default gen_random_uuid() not null,trip_id uuid not null,user_id uuid not null,category_id uuid,amount numeric not null,currency text default 'BRL'::text not null,date date not null,description text,paid_by text,receipt_url text,created_at timestamp with time zone default timezone('utc'::text, now()),status text default 'PENDENTE'::text);
create table public.trip_shares (id uuid default gen_random_uuid() not null,trip_id uuid not null,shared_by uuid not null,shared_with_email text not null,permission text default 'WRITE'::text not null,status text default 'PENDING'::text not null,created_at timestamp with time zone default timezone('utc'::text, now()));
create table public.trips (id uuid default gen_random_uuid() not null,user_id uuid not null,title text not null,cities text[] default '{}'::text[] not null,countries text[] default '{}'::text[] not null,hotels jsonb default '[]'::jsonb not null,transports jsonb default '[]'::jsonb not null,daily_limit numeric default 0,currencies text[] default '{BRL}'::text[] not null,start_date date,end_date date,receipts jsonb default '[]'::jsonb not null,created_at timestamp with time zone default timezone('utc'::text, now()),updated_at timestamp with time zone default timezone('utc'::text, now()),participants text[] default '{}'::text[],daily_limits jsonb default '{}'::jsonb,tickets jsonb default '[]'::jsonb,misc_docs jsonb default '[]'::jsonb);
