alter table mf_account_types add constraint mf_account_types_name_check CHECK (((char_length(btrim(name)) >= 1) AND (char_length(btrim(name)) <= 40)));
alter table mf_categories add constraint mf_categories_check CHECK (((parent_id IS NULL) OR (parent_id <> id)));
alter table mf_import_rows add constraint mf_import_rows_status_check CHECK ((status = ANY (ARRAY['NEW'::text, 'SUGGESTED'::text, 'MATCHED'::text, 'IGNORED'::text])));
alter table mf_budgets add constraint mf_budgets_check1 CHECK ((((
CASE
    WHEN (category_id IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN (tag_id IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN (account_id IS NOT NULL) THEN 1
    ELSE 0
END) <= 1));
alter table mf_categories add constraint mf_categories_type_check CHECK ((type = ANY (ARRAY['DESPESA'::text, 'RECEITA'::text, 'AMBAS'::text])));
alter table trip_shares add constraint trip_shares_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'ACCEPTED'::text, 'REJECTED'::text])));
alter table mf_budgets add constraint mf_budgets_check CHECK ((period_end >= period_start));
alter table mf_invoices add constraint mf_invoices_total_source_check CHECK ((total_source = ANY (ARRAY['derived'::text, 'manual'::text, 'imported'::text])));
alter table mf_import_batches add constraint mf_import_batches_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'REVIEWED'::text, 'COMPLETED'::text, 'CANCELLED'::text])));
alter table mf_accounts add constraint mf_accounts_account_type_check CHECK (((char_length(btrim(account_type)) >= 1) AND (char_length(btrim(account_type)) <= 60)));
alter table mf_accounts add constraint mf_accounts_closing_day_check CHECK (((closing_day >= 1) AND (closing_day <= 31)));
alter table mf_transactions add constraint mf_transactions_amount_check CHECK ((amount <> (0)::numeric));
alter table mf_accounts add constraint mf_accounts_currency_check CHECK (((char_length(currency) = 3) AND (currency = upper(currency))));
alter table mf_transactions add constraint mf_transactions_check CHECK (((type <> 'TRANSFERENCIA'::text) OR (transfer_account_id IS NOT NULL)));
alter table mf_transactions add constraint mf_transactions_check1 CHECK (((type <> 'TRANSFERENCIA'::text) OR (category_id IS NULL)));
alter table mf_transactions add constraint mf_transactions_check2 CHECK ((((installments_current IS NULL) AND (installments_total IS NULL)) OR ((installments_current >= 1) AND (installments_total >= 1) AND (installments_current <= installments_total))));
alter table mf_transactions add constraint mf_transactions_check3 CHECK (((parent_transaction_id IS NULL) OR ((installments_current IS NOT NULL) OR (recurrence <> 'NONE'::text))));
alter table mf_accounts add constraint mf_accounts_due_day_check CHECK (((due_day >= 1) AND (due_day <= 31)));
alter table mf_goal_contributions add constraint mf_goal_contributions_kind_check CHECK ((kind = ANY (ARRAY['DEPOSIT'::text, 'WITHDRAW'::text])));
alter table mf_goal_contributions add constraint mf_goal_contributions_amount_check CHECK ((amount > (0)::numeric));
alter table mf_transactions add constraint mf_transactions_recurrence_check CHECK ((recurrence = ANY (ARRAY['NONE'::text, 'WEEKLY'::text, 'MONTHLY'::text, 'YEARLY'::text])));
alter table mf_card_settings add constraint mf_card_settings_effective_from_fmt CHECK ((effective_from ~ '^[0-9]{4}-[0-9]{2}$'::text));
alter table mf_transactions add constraint mf_transactions_status_check CHECK ((status = ANY (ARRAY['PENDENTE'::text, 'PAGO'::text, 'CANCELADO'::text])));
alter table mf_invoices add constraint mf_invoices_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'PAID'::text, 'SCHEDULED'::text, 'OVERDUE'::text])));
alter table mf_transactions add constraint mf_transactions_type_check CHECK ((type = ANY (ARRAY['DESPESA'::text, 'RECEITA'::text, 'TRANSFERENCIA'::text])));
alter table mf_import_batches add constraint mf_import_batches_format_check CHECK ((format = ANY (ARRAY['OFX'::text, 'CSV'::text, 'XLSX'::text])));
alter table mf_budgets add constraint mf_budgets_mode_check CHECK ((mode = ANY (ARRAY['FIXED'::text, 'PERCENT'::text])));
alter table trip_shares add constraint trip_shares_permission_check CHECK ((permission = ANY (ARRAY['READ'::text, 'WRITE'::text])));
alter table mf_account_groups add constraint mf_account_groups_check CHECK (((parent_id IS NULL) OR (parent_id <> id)));
alter table mf_budgets add constraint mf_budgets_check2 CHECK ((((mode = 'FIXED'::text) AND (amount IS NOT NULL) AND (amount > (0)::numeric) AND (percent_of_income IS NULL)) OR ((mode = 'PERCENT'::text) AND (percent_of_income IS NOT NULL) AND (percent_of_income > (0)::numeric) AND (amount IS NULL))));
alter table mf_goals add constraint mf_goals_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'COMPLETED'::text, 'ARCHIVED'::text])));
alter table mf_goals add constraint mf_goals_target_amount_check CHECK ((target_amount > (0)::numeric));

